(function(){if(typeof ApexCharts==='undefined')return;var rows=<?=json_encode($series,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;var cats=rows.map(function(x){return x.label});var keys=['pokok','bunga','denda','collection_rescheduling','pencairan','denda_dibebaskan','pelunasan_lain'];var names=['Pokok terkumpul','Bunga diterima','Denda diterima','Collection rescheduling','Pencairan (arus keluar)','Denda dibebaskan','Pelunasan lain'];var data=keys.map(function(k,i){return{name:names[i],data:rows.map(function(x){return k==='pencairan'?-Number(x[k]):Number(x[k])})}});new ApexCharts(document.querySelector('#labaKasChart'),{chart:{type:'line',height:360,zoom:{enabled:true,type:'x',autoScaleYaxis:true},toolbar:{show:true,autoSelected:'zoom'},fontFamily:'inherit'},series:data,colors:['#64748b','#2563eb','#dc2626','#7c3aed','#f97316','#0f766e','#94a3b8'],stroke:{width:[2,3,3,2,2,2,2],curve:'smooth',dashArray:[0,0,0,0,0,6,4]},dataLabels:{enabled:false},xaxis:{categories:cats,labels:{rotate:-35}},yaxis:{labels:{formatter:function(v){return 'Rp '+new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(Math.abs(v))}}},tooltip:{shared:true,y:{formatter:function(v){return 'Rp '+new Intl.NumberFormat('id-ID').format(Math.abs(v))}}},legend:{position:'top'},grid:{borderColor:'#e2e8f0',strokeDashArray:4},noData:{text:'Tidak ada transaksi pada periode ini'}}).render();})();
